// secretsRig builds the minimal GET /admin/plugins rig for the tmdb-enrichment
// 3.3 tests: one plugin ("tmdb") bound as scanner (module image) and as
// metadata source by TWO modules (tv priority 3, serial priority 4 — the real
// seed's disagreeing pair), each metadata binding with its own options JSON.
// verdicts is the canned Deps.RequiredSecretsStatus answer per (moduleID,
// pluginID).
func secretsRig(t *testing.T, verdicts func(moduleID, pluginID string) map[string]bool) http.Handler {
	t.Helper()
	configs := map[string][]fakeBinding{
		"tmdb": {
			{moduleID: "image", kind: "scanner", options: `{"poster_dir":"/srv/art"}`},
			{moduleID: "tv", kind: "metadata", priority: 3, enabled: true, authMode: "SERVER",
				options: `{"api_key":"tv-secret","language":"en-US"}`},
			{moduleID: "serial", kind: "metadata", priority: 4, enabled: true, authMode: "SERVER",
				options: `{"language":"ru-RU"}`},
		},
	}
	return New(Deps{
		AdminToken: adminToken,
		Store:      openAPIStore(t),
		SourceInventory: func(context.Context) ([]string, map[string]string, map[string]string) {
			return []string{"tmdb"}, map[string]string{"tmdb": "TMDB"}, nil
		},
		ModuleIDs: func(context.Context) ([]string, error) { return []string{"tv", "serial", "image"}, nil },
		// The gate resolution is not this test's subject — every module
		// resolves to an empty chain (the effective block stays nil).
		ModuleSources: func(context.Context, string, int64) ([]string, []int, []bool, error) {
			return []string{}, []int{}, []bool{}, nil
		},
		PluginConfigs: fakePluginConfigs(configs),
		// A nil verdicts arg leaves the Deps field nil (today's degradation
		// path); a non-nil one is the canned per-binding answer.
		RequiredSecretsStatus: verdicts,
	})
}

// fetchSecretBindings GETs the aggregate as admin and returns the tmdb row's
// binding rows indexed by module id, plus the RAW envelope for the loose
// wire-shape checks (the typed decode cannot prove key absence). The
// aggregate is fetched twice because the body is consumed by each decode.
func fetchSecretBindings(t *testing.T, h http.Handler) (map[string]pluginAdminBinding, map[string]map[string]any) {
	t.Helper()
	resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var raw struct {
		Plugins []map[string]any `json:"plugins"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&raw); err != nil {
		t.Fatalf("decode raw envelope: %v", err)
	}
	if len(raw.Plugins) != 1 || raw.Plugins[0]["plugin_id"] != "tmdb" {
		t.Fatalf("plugins = %+v, want exactly the tmdb row", raw.Plugins)
	}
	// The plugin row itself carries NO single verdict: required_secrets (and
	// any bare provided key) live on the binding rows only, never at the
	// plugin-row top level.
	for _, key := range []string{"required_secrets", "provided"} {
		if _, present := raw.Plugins[0][key]; present {
			t.Fatalf("tmdb plugin row carries a top-level %q key — verdicts must be per binding", key)
		}
	}
	cfgRaw, ok := raw.Plugins[0]["config"].([]any)
	if !ok {
		t.Fatalf("tmdb config = %v, want a binding array", raw.Plugins[0]["config"])
	}
	rawByModule := make(map[string]map[string]any, len(cfgRaw))
	for _, entry := range cfgRaw {
		row, ok := entry.(map[string]any)
		if !ok {
			t.Fatalf("binding row %v is not an object", entry)
		}
		moduleID, _ := row["module_id"].(string)
		rawByModule[moduleID] = row
	}
	var typed pluginAdminResponse
	resp = doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins", "", adminToken)
	defer resp.Body.Close()
	if err := json.NewDecoder(resp.Body).Decode(&typed); err != nil {
		t.Fatalf("decode pluginAdminResponse: %v", err)
	}
	typedByModule := make(map[string]pluginAdminBinding, len(cfgRaw))
	for _, b := range typed.Plugins[0].Config {
		typedByModule[b.ModuleID] = b
	}
	return typedByModule, rawByModule
}

// TestAdminPluginsBindingSecretVerdicts is the per-binding verdicts test
// (tmdb-enrichment 3.3): one plugin bound by two modules renders EACH
// binding's OWN required_secrets verdicts (tv provided, serial not — the
// disagreeing pair), the scanner binding carries none, and the plugin row
// carries no single provided verdict at the top level.
func TestAdminPluginsBindingSecretVerdicts(t *testing.T) {
	h := secretsRig(t, func(moduleID, _ string) map[string]bool {
		if moduleID == "tv" {
			return map[string]bool{"api_key": true}
		}
		return map[string]bool{"api_key": false}
	})
	typed, raw := fetchSecretBindings(t, h)

	tv, ok := typed["tv"]
	if !ok || tv.RequiredSecrets == nil || len(tv.RequiredSecrets) != 1 || !tv.RequiredSecrets["api_key"] {
		t.Fatalf("tv binding verdicts = %+v, want {api_key: true}", tv.RequiredSecrets)
	}
	serial, ok := typed["serial"]
	if !ok || serial.RequiredSecrets == nil || len(serial.RequiredSecrets) != 1 || serial.RequiredSecrets["api_key"] {
		t.Fatalf("serial binding verdicts = %+v, want {api_key: false}", serial.RequiredSecrets)
	}
	sc, ok := typed["image"]
	if !ok || sc.RequiredSecrets != nil {
		t.Fatalf("scanner binding verdicts = %+v, want absent (no declarations on the scanner slot)", sc.RequiredSecrets)
	}

	// The verdicts ride the binding rows, not the plugin row (proved in the
	// helper) — here the tv binding's own map is the provided side.
	verdicts, ok := raw["tv"]["required_secrets"].(map[string]any)
	if !ok {
		t.Fatalf("tv binding required_secrets wire = %v, want an object", raw["tv"]["required_secrets"])
	}
	if verdicts["api_key"] != true {
		t.Fatalf("tv binding api_key verdict wire = %v, want true", verdicts["api_key"])
	}
	serialVerdicts, ok := raw["serial"]["required_secrets"].(map[string]any)
	if !ok {
		t.Fatalf("serial binding required_secrets wire = %v, want an object", raw["serial"]["required_secrets"])
	}
	if serialVerdicts["api_key"] != false {
		t.Fatalf("serial binding api_key verdict wire = %v, want false", serialVerdicts["api_key"])
	}
	if _, leaks := raw["serial"]["provided"]; leaks {
		t.Fatalf("serial binding carries a bare provided key — the verdict shape is name→bool, not a bare bool")
	}
}

// TestAdminPluginsBindingOptionsRedactSecrets is the serve-side redaction
// test (tmdb-enrichment 3.3): a metadata binding's stored options carrying a
// declared secret name serve WITHOUT that key, the ordinary keys verbatim;
// a binding whose options hold no declared name serves the stored bytes
// byte-identically.
func TestAdminPluginsBindingOptionsRedactSecrets(t *testing.T) {
	h := secretsRig(t, func(moduleID, _ string) map[string]bool {
		if moduleID == "tv" {
			return map[string]bool{"api_key": true}
		}
		return map[string]bool{"api_key": false}
	})
	typed, raw := fetchSecretBindings(t, h)

	if got := string(typed["tv"].Options); got != `{"language":"en-US"}` {
		t.Fatalf("tv served options = %s, want the secret key omitted, ordinary keys verbatim", got)
	}
	if got := string(typed["serial"].Options); got != `{"language":"ru-RU"}` {
		t.Fatalf("serial served options = %s, want verbatim (no declared key present)", got)
	}
	// The scanner slot has no metadata declaration behind it: its options
	// serve verbatim, redaction never touches it.
	if got := string(typed["image"].Options); got != `{"poster_dir":"/srv/art"}` {
		t.Fatalf("scanner served options = %s, want verbatim", got)
	}
	// Loose check: the secret VALUE never rides the bytes.
	for moduleID, row := range raw {
		optsJSON, err := json.Marshal(row["options"])
		if err != nil {
			t.Fatalf("marshal %s options: %v", moduleID, err)
		}
		var opts map[string]any
		if err := json.Unmarshal(optsJSON, &opts); err == nil {
			if _, leak := opts["api_key"]; leak {
				t.Fatalf("%s binding served options leak api_key: %s", moduleID, optsJSON)
			}
		}
	}
}

// TestAdminPluginsNoDeclarationsUnchanged is the byte-identical degradation
// test (tmdb-enrichment 3.3): a plugin whose closure answer carries NO
// declarations (nil maps) serves today's row shape exactly — no
// required_secrets key anywhere on the wire, options stored bytes verbatim.
func TestAdminPluginsNoDeclarationsUnchanged(t *testing.T) {
	h := secretsRig(t, func(string, string) map[string]bool { return nil })
	typed, raw := fetchSecretBindings(t, h)

	wantOptions := map[string]string{
		"image":  `{"poster_dir":"/srv/art"}`,
		"tv":     `{"api_key":"tv-secret","language":"en-US"}`,
		"serial": `{"language":"ru-RU"}`,
	}
	for moduleID, want := range wantOptions {
		if got := string(typed[moduleID].Options); got != want {
			t.Fatalf("%s served options = %s, want stored bytes verbatim %s", moduleID, got, want)
		}
		if typed[moduleID].RequiredSecrets != nil {
			t.Fatalf("%s typed verdicts = %+v, want nil (no declarations)", moduleID, typed[moduleID].RequiredSecrets)
		}
		if _, present := raw[moduleID]["required_secrets"]; present {
			t.Fatalf("%s binding carries a required_secrets key — a no-declaration row must keep today's shape byte-identically", moduleID)
		}
		if _, present := raw[moduleID]["provided"]; present {
			t.Fatalf("%s binding carries a provided key — today's shape has none", moduleID)
		}
	}
}
